 const c=s.capabilities;c.profiles||={};c.skills||=[];c.connections||=[];c.settings||={maximumShare:'organization'};
 for(const a of s.agents.filter(a=>a.type==='agent'))if(!c.profiles[a.id])c.profiles[a.id]={stage:a.status==='active'?'production':a.status==='pilot'?'pilot':'qualification',visibility:'team',favorite:a.id==='a-beacon',description:a.mandate?.mission||a.role,requiredApps:appTemplates.filter(t=>(a.mandate?.tools||[]).includes(t.name)).map(t=>t.id),revision:1,tests:[],testedRevision:null,pilotEvidence:a.status==='active'?'Historique fictif du scénario initial':null,source:'initial'};
