export function runPilot(s,id){const c=ensureCapabilities(s),p=c.profiles[id],a=s.agents.find(x=>x.id===id);if(!p||p.stage!=='pilot')fail('L’agent doit être en pilote.');if(a?.status==='paused')fail('Réactivez cet agent avant son pilote.');if(p.requiredApps.some(app=>!availableConnection(s,app)))fail('Les accès requis ne sont pas tous approuvés.');p.pilotEvidence=`Cas pilote local exécuté le ${now()} : un dossier fictif préparé, justificatifs présents et aucune action externe. Revue humaine requise.`;return p.pilotEvidence}
export function evaluateSkill(skill,input){
 let data;try{data=JSON.parse(input)}catch{return 'INVALID_INPUT'}
 if(!data||typeof data!=='object'||Array.isArray(data))return 'INVALID_INPUT';
 if(skill.evaluator==='sources')return data.author&&data.date&&data.source?'VERIFIED':'REVIEW';
 if(skill.evaluator==='reconcile'){if(!Number.isFinite(data.left)||!Number.isFinite(data.right))return 'INVALID_INPUT';return Math.abs(data.left-data.right)<=Math.max(0,Number(data.tolerance)||0)?'MATCH':'REVIEW'}
 return typeof data.content==='string'&&data.content.trim()?'COMPLETE':'REVIEW';
}
