export function reviseSkill(skill,patch){Object.assign(skill,patch);skill.revision+=1;skill.status='draft';skill.reviewed=false;skill.testedRevision=null;skill.testResults=[];for(const l of skill.learners){l.status='learning';l.score=null;l.testedRevision=null}return skill}
export function runSkillTests(s,id){const skill=ensureCapabilities(s).skills.find(x=>x.id===id);if(!skill)fail('Compétence introuvable.');if(!skill.steps.length||!skill.tests.length)fail('Ajoutez des étapes et au moins un test.');skill.testResults=skill.tests.map(t=>({id:t.id,actual:evaluateSkill(skill,t.input),passed:evaluateSkill(skill,t.input)===t.expected,at:now()}));skill.testedRevision=skill.revision;return skill.testResults}
export function publishSkill(s,id,reviewed){const skill=ensureCapabilities(s).skills.find(x=>x.id===id);if(!skill)fail('Compétence introuvable.');if(!reviewed)fail('La revue humaine des étapes et du périmètre est requise.');if(skill.testedRevision!==skill.revision||skill.testResults.length!==skill.tests.length||!skill.tests.length||skill.testResults.some(t=>!t.passed))fail('Tous les tests de la version actuelle doivent réussir.');if(skill.apps.some(app=>!availableConnection(s,app)))fail('Une application utilisée n’est pas approuvée.');if(skill.status!=='published'&&skill.publishedAt)skill.version+=1;skill.status='published';skill.reviewed=true;skill.publishedAt=now();return skill}
export function assignLearners(s,id,actorIds){const skill=ensureCapabilities(s).skills.find(x=>x.id===id);if(!skill||skill.status!=='published')fail('Publiez la compétence avant d’inscrire des apprenants.');for(const actorId of actorIds){if(!s.agents.some(x=>x.id===actorId))fail('Apprenant introuvable.');if(!skill.learners.some(l=>l.actorId===actorId))skill.learners.push({actorId,status:'learning',score:null,testedRevision:null,uses:0})}return skill.learners}
export function evaluateLearner(s,id,actorId){const skill=ensureCapabilities(s).skills.find(x=>x.id===id),learner=skill?.learners.find(x=>x.actorId===actorId);if(!skill||!learner)fail('Apprenant introuvable.');if(skill.status!=='published')fail('La compétence doit être publiée.');if(skill.apps.some(app=>!availableConnection(s,app)))fail('Une application nécessaire n’est plus approuvée.');const results=skill.tests.map(t=>({id:t.id,actual:evaluateSkill(skill,t.input),passed:evaluateSkill(skill,t.input)===t.expected}));learner.score=Math.round(results.filter(t=>t.passed).length/Math.max(results.length,1)*100);learner.results=results;learner.testedRevision=skill.revision;learner.status=learner.score===100?'review':'learning';learner.evaluatedAt=now();return learner}
export function certifyLearner(s,id,actorId){const skill=ensureCapabilities(s).skills.find(x=>x.id===id),learner=skill?.learners.find(x=>x.actorId===actorId),actor=s.agents.find(x=>x.id===actorId);if(!skill||!learner||!actor)fail('Apprenant introuvable.');if(skill.status!=='published'||learner.status!=='review'||learner.score!==100||learner.testedRevision!==skill.revision)fail('Une évaluation réussie sur la version publiée est requise.');if(skill.apps.some(app=>!availableConnection(s,app)))fail('Une application nécessaire n’est plus approuvée.');learner.status='certified';learner.certifiedAt=now();actor.skills||=[];if(!actor.skills.includes(skill.name))actor.skills.push(skill.name);return learner}
