export function buildConnection(s,data){const c=ensureCapabilities(s),name=String(data.name||'').trim(),description=String(data.description||'').trim();if(!name||!description)fail('Un nom et une description sont requis.');const connection={id:uid('app'),name,short:name[0].toUpperCase(),description,category:'Sur mesure',tools:[{name:'read_records',mode:'read',scope:'records:read'},{name:'prepare_draft',mode:'write',scope:'drafts:write'}],owner:data.owner||'Matthieu Keip',team:'Opérations',origin:'built',status:'needs-review',revision:1,testedRevision:null,testResult:null,reviewed:false,scopes:['records:read'],visibility:'private',simulation:true};c.connections.push(connection);return connection}
